import { operation } from "@tinker/core";
import { z } from "zod";

import { database, transaction } from "~/components/database-sqlite/index.server";
import { raise } from "~/components/errors";

import { blobBytes } from "./bytes.server";
import { blobCrypto } from "./modules";
import deleteSlot from "./queries/delete_slot.sql";
import fillSlotQuery from "./queries/fill_slot.sql";
import insertBlob from "./queries/insert_blob.sql";
import insertSlot from "./queries/insert_slot.sql";
import pruneSlots from "./queries/prune_slots.sql";
import readBlobQuery from "./queries/read_blob.sql";
import readSlot from "./queries/read_slot.sql";
import { blobMaxBytes, blobSlotTtl } from "./tags";

/** A blob's name: its sha256 as lower-case hex. Anything else never reaches the file system. */
const blobHash = /^[0-9a-f]{64}$/;

/** Store `bytes` once under their sha256. The row is written after the file is in place. */
export const putBlob = operation({
  label: "blobs.put",
  input: z.strictObject({ bytes: z.instanceof(Uint8Array) }),
  depends: { store: blobBytes, transaction, maxBytes: blobMaxBytes },
  run: async ({ store, transaction, maxBytes }, { input, clock, signal }) => {
    if (input.bytes.byteLength > maxBytes) raise("BlobTooBig", { maxBytes });

    if (input.bytes.byteLength === 0) raise("BlobEmpty", {});

    // The byte side reads one stream shape, so the whole buffer becomes a one-chunk stream.
    const body = new ReadableStream<Uint8Array>({
      start(controller) {
        controller.enqueue(input.bytes);
        controller.close();
      },
    });

    const stored = await store.write(body, maxBytes, signal);

    insertBlob.runSync(await transaction.db(), {
      hash: stored.hash,
      size: stored.size,
      created_at: clock.currentTimeMillis(),
    });

    return stored;
  },
});

/** The bytes of a stored blob, or `undefined`: a blob needs its row and its file. */
export const readBlob = operation({
  label: "blobs.read",
  input: z.strictObject({ hash: z.string() }),
  depends: { database, store: blobBytes },
  run: async ({ database, store }, { input }) => {
    if (!blobHash.test(input.hash)) return undefined;

    if (!readBlobQuery.runSync(database.reader, { hash: input.hash })) return undefined;

    return store.read(input.hash);
  },
});

/** Open an upload slot for `owner`. Expired slots are deleted in the same transaction. */
export const openSlot = operation({
  label: "blobs.openSlot",
  input: z.strictObject({
    owner: z.string().min(1).max(200),
    maxBytes: z.number().int().min(1).optional(),
  }),
  depends: { transaction, crypto: blobCrypto, limit: blobMaxBytes, ttl: blobSlotTtl },
  run: async ({ transaction, crypto, limit, ttl }, { input, clock }) => {
    const maxBytes = input.maxBytes ?? limit;

    if (maxBytes > limit) raise("BlobTooBig", { maxBytes: limit });

    const id = `up_${crypto.randomBytes(12).toString("hex")}`;

    const now = clock.currentTimeMillis();

    const expiresAt = now + ttl;

    const connection = await transaction.db();

    pruneSlots.runSync(connection, { now });

    insertSlot.runSync(connection, {
      id,
      owner: input.owner,
      max_bytes: maxBytes,
      expires_at: expiresAt,
    });

    return { id, expiresAt, maxBytes };
  },
});

/**
 * Read a byte stream into a slot. The bytes stream in with no write turn held; the slot is
 * filled by one conditional update, so of two fills only the first to commit wins.
 */
export const fillSlot = operation({
  label: "blobs.fillSlot",
  input: z.strictObject({
    id: z.string(),
    body: z.instanceof(ReadableStream<Uint8Array>),
    name: z.string().max(200).optional(),
  }),
  depends: { database, transaction, store: blobBytes },
  run: async ({ database, transaction, store }, { input, clock, signal }) => {
    // A bad id finds no row, so it reads the same as an unknown one.
    const slot = readSlot.runSync(database.reader, { id: input.id });

    if (!slot) raise("SlotMissing", {});

    if (slot.hash !== null) raise("SlotUsed", {});

    if (clock.currentTimeMillis() >= slot.expires_at) raise("SlotExpired", {});

    const stored = await store.write(input.body, slot.max_bytes, signal);

    const connection = await transaction.db();

    const now = clock.currentTimeMillis();

    insertBlob.runSync(connection, { hash: stored.hash, size: stored.size, created_at: now });

    const filled = fillSlotQuery.runSync(connection, {
      id: input.id,
      hash: stored.hash,
      size: stored.size,
      name: input.name ?? null,
      filled_at: now,
      now,
    });

    if (!filled) {
      // The update found no open slot: say why, from what the slot holds now.
      const current = readSlot.runSync(connection, { id: input.id });

      if (!current) raise("SlotMissing", {});

      if (current.hash !== null) raise("SlotUsed", {});

      raise("SlotExpired", {});
    }

    return { id: input.id, hash: stored.hash, size: stored.size };
  },
});

/** Hand a filled slot's blob to its owner once. The caller reads the bytes with `readBlob`. */
export const takeSlot = operation({
  label: "blobs.takeSlot",
  input: z.strictObject({ id: z.string(), owner: z.string().min(1).max(200) }),
  depends: { transaction },
  run: async ({ transaction }, { input, clock }) => {
    const connection = await transaction.db();

    const slot = readSlot.runSync(connection, { id: input.id });

    // Another owner reads the same as an unknown id: it does not learn the slot exists.
    if (!slot || slot.owner !== input.owner) raise("SlotMissing", {});

    if (clock.currentTimeMillis() >= slot.expires_at) raise("SlotExpired", {});

    if (slot.hash === null || slot.size === null) raise("SlotEmpty", {});

    deleteSlot.runSync(connection, { id: input.id });

    return { hash: slot.hash, size: slot.size, name: slot.name };
  },
});

import { resource, tag } from "@tinker/core";
import { z } from "zod";

import { raise } from "~/components/errors";

import { blobCrypto, blobFs, blobPath } from "./modules";
import { blobSlotTtl } from "./tags";

/** The absolute folder for the bytes. Temp files live in its `tmp/`, on the same disk. */
export const blobFolder = tag({
  label: "blobs.folder",
  parse: z.string().refine((path) => path.startsWith("/") || /^[A-Za-z]:[\\/]/.test(path), {
    error: "The blob folder needs an absolute path",
  }),
});

/**
 * The byte side of the store, the one part an S3 copy replaces: a file under
 * `<blobFolder>/<2 hex>/<sha256>` appears only by renaming a whole, fsynced temp.
 */
export const blobBytes = resource({
  label: "blobs.bytes",
  depends: { folder: blobFolder, ttl: blobSlotTtl, fs: blobFs, crypto: blobCrypto, path: blobPath },
  factory: async ({ folder, ttl, fs, crypto, path }, { clock }) => {
    const temps = path.join(folder, "tmp");

    await fs.mkdir(temps, { recursive: true });

    // Crash leftovers go; a younger temp may be another process mid-write.
    for (const name of await fs.readdir(temps)) {
      const file = path.join(temps, name);

      const info = await fs.stat(file).catch(() => undefined);

      if (info && info.mtimeMs < clock.currentTimeMillis() - ttl) {
        await fs.rm(file, { force: true });
      }
    }

    const bytes = {
      /**
       * Read `body` into a temp, stopping past `maxBytes` or at `signal`, then rename it into
       * place under its sha256. A failure removes the temp and cancels the body.
       */
      async write(body: ReadableStream<Uint8Array>, maxBytes: number, signal: AbortSignal) {
        signal.throwIfAborted();

        const temp = path.join(temps, crypto.randomBytes(12).toString("hex"));

        const reader = body.getReader();

        // A client that goes away ends the read now; the copy then throws the abort reason.
        const stop = () => void reader.cancel(signal.reason).catch(() => {});

        signal.addEventListener("abort", stop, { once: true });

        try {
          const stored = await bytes.copy(reader, temp, maxBytes, signal);

          await bytes.place(temp, stored.hash);

          return stored;
        } catch (error) {
          await reader.cancel(error).catch(() => {});
          await fs.rm(temp, { force: true });

          throw error;
        } finally {
          signal.removeEventListener("abort", stop);
        }
      },

      /** Copy the stream into a new temp file, hashing as it goes, and fsync it before close. */
      async copy(
        reader: ReadableStreamDefaultReader<Uint8Array>,
        temp: string,
        maxBytes: number,
        signal: AbortSignal,
      ) {
        const hasher = crypto.createHash("sha256");

        const file = await fs.open(temp, "wx");

        let size = 0;

        try {
          while (true) {
            const chunk = await reader.read();

            signal.throwIfAborted();

            if (chunk.done) break;

            size += chunk.value.byteLength;

            if (size > maxBytes) raise("BlobTooBig", { maxBytes });

            hasher.update(chunk.value);

            for (let offset = 0; offset < chunk.value.byteLength;) {
              offset += (await file.write(chunk.value, offset)).bytesWritten;
            }
          }

          if (size === 0) raise("BlobEmpty", {});

          await file.sync();
        } finally {
          await file.close();
        }

        return { hash: hasher.digest("hex"), size };
      },

      /** Rename a whole temp to its hash path; the same bytes already in place stay untouched. */
      async place(temp: string, hash: string) {
        const final = path.join(folder, hash.slice(0, 2), hash);

        const present = await fs.stat(final).then(
          () => true,
          () => false,
        );

        if (present) return fs.rm(temp, { force: true });

        const shelf = path.dirname(final);

        const made = await fs.mkdir(shelf, { recursive: true });

        await fs.rename(temp, final);

        // The rename and a new shelf are durable only once their folders are fsynced.
        for (const dir of made ? [shelf, folder] : [shelf]) {
          const handle = await fs.open(dir, "r");

          try {
            await handle.sync();
          } finally {
            await handle.close();
          }
        }
      },

      /** The bytes stored under `hash`, or `undefined` when its file is gone. */
      async read(hash: string) {
        try {
          const buffer = await fs.readFile(path.join(folder, hash.slice(0, 2), hash));

          return new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength);
        } catch (error) {
          if (error instanceof Error && "code" in error && error.code === "ENOENT") {
            return undefined;
          }

          throw error;
        }
      },
    };

    return bytes;
  },
});

export { blobMaxBytes, blobSlotTtl, blobUnpackMax } from "./tags";

export { blobFolder } from "./bytes.server";

export { fillSlot, openSlot, putBlob, readBlob, takeSlot } from "./blobs.server";

import { resource } from "@tinker/core";

export const blobFs = resource({
  label: "module:node:fs/promises",
  target: "scope",
  factory: () => import("node:fs/promises"),
});

export const blobCrypto = resource({
  label: "module:node:crypto",
  target: "scope",
  factory: () => import("node:crypto"),
});

export const blobPath = resource({
  label: "module:node:path",
  target: "scope",
  factory: () => import("node:path"),
});

import { tag } from "@tinker/core";
import { z } from "zod";

/** The most bytes one blob may hold: 25 MiB, obelisk's `MAX_UPLOAD`. */
export const blobMaxBytes = tag<number>({
  label: "blobs.maxBytes",
  default: 26_214_400,
  parse: z.number().int().positive(),
});

/** How long an upload slot lives, in ms: one hour, as in obelisk. */
export const blobSlotTtl = tag<number>({
  label: "blobs.slotTtl",
  default: 3_600_000,
  parse: z.number().int().positive(),
});

/** The most bytes a zip may unpack to, all entries together. The app's zip reader reads it. */
export const blobUnpackMax = tag<number>({
  label: "blobs.unpackMax",
  default: 104_857_600,
  parse: z.number().int().positive(),
});
